var step_6_default = "---\nlayout: tutorial\ntitle: Create CRUD pages\ndescription: Add database queries and CRUD pages using Appwrite in your Refine application.\nstep: 6\n---\n\nWe're going to add CRUD pages to our admin panel so you can list, create, and view blog posts records.\n\n\n## List page {% #list-page %}\n\n\n First, create a listing page to show Appwrite API data in a table by copying the code below into `src/pages/posts` and saving it as `list.tsx`.\n\n```ts\nimport { IResourceComponentsProps } from \"@refinedev/core\";\nimport {\n  List,\n  useTable,\n  EditButton,\n  ShowButton,\n  getDefaultSortOrder,\n  DeleteButton,\n} from \"@refinedev/antd\";\nimport { Table, Space } from \"antd\";\nimport { IPost } from \"../../interfaces\";\n\nexport const PostList: React.FC<IResourceComponentsProps> = () => {\n  const { tableProps, sorters } = useTable<IPost>({\n    initialSorter: [\n      {\n        field: \"$id\",\n        order: \"asc\",\n      },\n    ],\n  });\n\n  return (\n    <List>\n      <Table {...tableProps} rowKey=\"id\">\n        <Table.Column\n          dataIndex=\"id\"\n          title=\"ID\"\n          sorter\n          width={100}\n          defaultSortOrder={getDefaultSortOrder(\"id\", sorters)}\n        />\n        <Table.Column dataIndex=\"title\" title=\"Title\" sorter />\n\n        <Table.Column<IPost>\n          title=\"Actions\"\n          dataIndex=\"actions\"\n          fixed=\"right\"\n          render={(_, record) => (\n            <Space>\n              <EditButton hideText size=\"small\" recordItemId={record.id} />\n              <ShowButton hideText size=\"small\" recordItemId={record.id} />\n              <DeleteButton hideText size=\"small\" recordItemId={record.id} />\n            </Space>\n          )}\n        />\n      </Table>\n    </List>\n  );\n};\n```\n\n## Create page {% #create-page %}\n\n Create a new record page for the Appwrite API by copying the following code and saving it as `create.tsx`.\n\n\n```ts\nimport { HttpError, IResourceComponentsProps } from \"@refinedev/core\";\nimport { Create, useForm } from \"@refinedev/antd\";\nimport { Form, Input } from \"antd\";\nimport { IPost, IPostVariables } from \"../../interfaces\";\n\nexport const PostCreate: React.FC<IResourceComponentsProps> = () => {\n  const { formProps, saveButtonProps } = useForm<\n    IPost,\n    HttpError,\n    IPostVariables\n  >();\n\n  return (\n    <Create saveButtonProps={saveButtonProps}>\n      <Form {...formProps} layout=\"vertical\">\n        <Form.Item\n          label=\"Title\"\n          name=\"title\"\n          rules={[\n            {\n              required: true,\n            },\n          ]}\n        >\n          <Input />\n        </Form.Item>\n\n        <Form.Item\n          label=\"Content\"\n          name=\"content\"\n          rules={[\n            {\n              required: true,\n            },\n          ]}\n        >\n          <Input.TextArea rows={5} />\n        </Form.Item>\n      </Form>\n    </Create>\n  );\n};\n```\n\n## Edit page {% #edit-page %}\n\nCreate a page for editing a records with the following code and saving it as `edit.tsx`.\n\n\n```ts\nimport React from \"react\";\nimport { HttpError, IResourceComponentsProps } from \"@refinedev/core\";\nimport { Edit, useForm } from \"@refinedev/antd\";\nimport { Form, Input } from \"antd\";\nimport { IPost, IPostVariables } from \"../../interfaces\";\n\nexport const PostEdit: React.FC<IResourceComponentsProps> = () => {\n  const { formProps, saveButtonProps } = useForm<\n    IPost,\n    HttpError,\n    IPostVariables\n  >();\n\n  return (\n    <Edit saveButtonProps={saveButtonProps}>\n      <Form {...formProps} layout=\"vertical\">\n        <Form.Item\n          label=\"Title\"\n          name=\"title\"\n          rules={[\n            {\n              required: true,\n            },\n          ]}\n        >\n          <Input />\n        </Form.Item>\n        <Form.Item\n          label=\"Content\"\n          name=\"content\"\n          rules={[\n            {\n              required: true,\n            },\n          ]}\n        >\n          <Input.TextArea rows={5} />\n        </Form.Item>\n      </Form>\n    </Edit>\n  );\n};\n```\n\n## Show page {% #show-page %}\n\n Create a page for showig the records with the following code and saving it as `edit.tsx`.\n\n\n```ts\nimport { useShow, IResourceComponentsProps } from \"@refinedev/core\";\n\nimport { Show, MarkdownField } from \"@refinedev/antd\";\nimport { Typography } from \"antd\";\nimport { IPost } from \"../../interfaces\";\n\nconst { Title, Text } = Typography;\n\nexport const PostShow: React.FC<IResourceComponentsProps> = () => {\n  const { queryResult } = useShow<IPost>();\n  const { data, isLoading } = queryResult;\n  const record = data?.data;\n\n  return (\n    <Show isLoading={isLoading}>\n      <Title level={5}>Id</Title>\n      <Text>{record?.id}</Text>\n\n      <Title level={5}>Title</Title>\n      <Text>{record?.title}</Text>\n\n      <Title level={5}>Content</Title>\n      <MarkdownField value={record?.content} />\n    </Show>\n  );\n};\n```\n\n## Interfaces {% #interfaces %}\n\n We need to add interfaces to `src/interfaces/index.d.ts` file.\n\n\n```ts\nexport interface IFile {\n  name: string;\n  percent: number;\n  size: number;\n  status: \"error\" | \"success\" | \"done\" | \"uploading\" | \"removed\";\n  type: string;\n  uid: string;\n  url: string;\n}\n\nexport interface IPost {\n  id: string;\n  title: string;\n  content: string;\n}\n\nexport interface IPostVariables {\n  id: string;\n  title: string;\n  content: string;\n}\n```\n\n## Connect pages to the App\n\nFinally, import the pages into `App.tsx` and define them in the `<Route>` components. \n\nSimply, paste the following into `App.tsx`.\n\n\n```ts\nimport { Authenticated, Refine } from \"@refinedev/core\";\nimport { dataProvider, liveProvider } from \"@refinedev/appwrite\";\nimport {\n  AuthPage,\n  ErrorComponent,\n  RefineThemes,\n  ThemedLayoutV2,\n  useNotificationProvider,\n} from \"@refinedev/antd\";\nimport routerProvider, {\n  CatchAllNavigate,\n  DocumentTitleHandler,\n  NavigateToResource,\n  UnsavedChangesNotifier,\n} from \"@refinedev/react-router-v6\";\nimport \"@refinedev/antd/dist/reset.css\";\n\nimport { App as AntdApp, ConfigProvider } from \"antd\";\nimport { BrowserRouter, Outlet, Route, Routes } from \"react-router-dom\";\n\nimport { appwriteClient } from \"./utility\";\nimport { authProvider } from \"./authProvider\";\nimport { PostCreate, PostEdit, PostList, PostShow } from \"./pages/posts\";\n\nconst App: React.FC = () => (\n  <BrowserRouter>\n    <ConfigProvider theme={RefineThemes.Blue}>\n      <AntdApp>\n        <Refine\n          dataProvider={dataProvider(appwriteClient, {\n            databaseId: \"<APPWRITE_DATABASE_ID>\",\n          })}\n          liveProvider={liveProvider(appwriteClient, {\n            databaseId: \"<APPWRITE_DATABASE_ID>\",\n          })}\n          authProvider={authProvider}\n          routerProvider={routerProvider}\n          resources={[\n            {\n              name: \"<APPWRITE_TABLE_ID>\",\n              list: \"/posts\",\n              create: \"/posts/create\",\n              edit: \"/posts/edit/:id\",\n              show: \"/posts/show/:id\",\n              meta: {\n                label: \"Posts\",\n              },\n            },\n          ]}\n          notificationProvider={useNotificationProvider}\n          options={{\n            liveMode: \"auto\",\n            syncWithLocation: true,\n            warnWhenUnsavedChanges: true,\n          }}\n        >\n          <Routes>\n            <Route\n              element={\n                <Authenticated \n                  fallback={<CatchAllNavigate to=\"/login\" />}\n                >\n                  <ThemedLayoutV2>\n                    <Outlet />\n                  </ThemedLayoutV2>\n                </Authenticated>\n              }\n            >\n              <Route\n                index\n                element={\n                  <NavigateToResource \n                    resource=\"<APPWRITE_TABLE_ID>\" \n                  />\n                }\n              />\n\n              <Route path=\"/posts\">\n                <Route index element={<PostList />} />\n                <Route path=\"create\" element={<PostCreate />} />\n                <Route path=\"edit/:id\" element={<PostEdit />} />\n                <Route path=\"show/:id\" element={<PostShow />} />\n              </Route>\n            </Route>\n\n            <Route\n              element={\n                <Authenticated fallback={<Outlet />}>\n                  <NavigateToResource\n                    resource=\"<APPWRITE_TABLE_ID>\" \n                  />\n                </Authenticated>\n              }\n            >\n              <Route\n                path=\"/login\"\n                element={<AuthPage forgotPasswordLink={false} />}\n              />\n              <Route path=\"/register\" \n                element={<AuthPage type=\"register\" />} \n              />\n            </Route>\n\n            <Route\n              element={\n                <Authenticated>\n                  <ThemedLayoutV2>\n                    <Outlet />\n                  </ThemedLayoutV2>\n                </Authenticated>\n              }\n            >\n              <Route path=\"*\" element={<ErrorComponent />} />\n            </Route>\n          </Routes>\n          <UnsavedChangesNotifier />\n          <DocumentTitleHandler />\n        </Refine>\n      </AntdApp>\n    </ConfigProvider>\n  </BrowserRouter>\n);\n\nexport default App;\n```\n\n";
export { step_6_default as default };
